import pyomo.environ as pyo

DATA = {
    "activities": ["X", "Y"],
    "resource_per_hour": {"X": 2, "Y": 3},
    "effort_per_hour": {"X": 5, "Y": 6},
    "max_total_hours": 10,
    "min_total_effort": 20,
}

GOLD_ANSWER = 8


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    model.ACT = pyo.Set(initialize=d["activities"])

    def hours_bounds(m, a):
        return (0, d["max_total_hours"])

    model.hours = pyo.Var(
        model.ACT,
        domain=pyo.NonNegativeIntegers,
        bounds=hours_bounds,
    )

    def total_hours_rule(m):
        return sum(m.hours[a] for a in m.ACT) <= d["max_total_hours"]

    model.total_hours_limit = pyo.Constraint(rule=total_hours_rule)

    def total_effort_rule(m):
        return sum(d["effort_per_hour"][a] * m.hours[a] for a in m.ACT) >= d["min_total_effort"]

    model.total_effort_limit = pyo.Constraint(rule=total_effort_rule)

    def obj_rule(m):
        return sum(d["resource_per_hour"][a] * m.hours[a] for a in m.ACT)

    model.obj = pyo.Objective(expr=obj_rule(model), sense=pyo.minimize)

    return model
